scoring_rules.system_query:
db.todos.aggregate([
  { $lookup: { from: "users", localField: "user_id", foreignField: "_id", as: "u" } },
  { $unwind: "$u" },
  { $project: {
    _id: 0,
    username_upper: { $toUpper: "$u.username" },
    email_length: { $strLenCP: "$u.email" },
    status_sub: { $substrCP: ["$status", 0, 3] },
    title_trimmed: { $trim: { input: "$title" } }
  } },
  { $sort: { username_upper: 1, title_trimmed: 1 } }
])

